function describe(n, depth) {
  const o = {name:n.name, type:n.type, w:Math.round(n.width||0), h:Math.round(n.height||0)};
  if (n.type==='TEXT') { o.chars = n.characters; o.fontSize = n.fontSize; try{o.font=n.fontName.family+'/'+n.fontName.style;}catch(e){o.font='mixed'} }
  if (n.cornerRadius!==undefined) o.r = n.cornerRadius;
  if (n.fills && n.fills.length) o.fills = n.fills.map(f=>({t:f.type, c: f.color ? [Math.round(f.color.r*255),Math.round(f.color.g*255),Math.round(f.color.b*255)] : undefined, o:f.opacity}));
  if (n.children && depth>0) o.children = n.children.map(c=>describe(c, depth-1));
  return o;
}
